import {applyResourceTerminology,energyText} from './vocabulary.js?v=0.3.1';
import {renderAtlas} from './full/map-view.js?v=0.3.1';
import {campaignCycleSummary,controlledRegionalCommands} from './world-bridge.js?v=0.3.1';
import {spendingChoices,actionAvailability} from './action-choices.js?v=0.3.1';
import {initializeGalacticOperations,convoyStatus,yardCapacity,stressZone,fleetCommitted,hasTransit} from './galaxy-operations.js?v=0.3.1';
import {bindTouchMap} from './touch-map.js?v=0.3.1';
import {newGame,command,endRound,planAI,FACTIONS,TECHS,UNITS,PRIORITIES,LAWS,faction,sector,colonies,fleets,income,distance,isTreaty,encodeSave,validateSave} from './engine.js?v=0.3.1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const practice=new URLSearchParams(location.search).get('practice')==='1';
const KEY='galactic-imperium.v1'+(practice?'.practice':'');
function read(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback;}catch{return fallback;}}
let settings=read(KEY+'.settings',{motion:true,sound:false});
let state;try{state=validateSave(read(KEY+'.auto',null));}catch{try{state=validateSave(read(KEY+'.backup',null));}catch{state=newGame();}}
initializeGalacticOperations(state);state.worldCampaigns=true;
let galacticTouchMap=null,galaxyPosition={left:0,top:0};
let view='galaxy',selected=state.sectors.find(x=>x.owner==='p')?.id||'-3,1',campaignId=null,groundSelected=null,groundType='advance',moveFrom=null,moveKind='move',zoom=1,busy=false,tab='research',tutorialStep=0;
let worker;try{worker=new Worker(new URL('./ai-worker.js?v=0.3.1',import.meta.url),{type:'module'});}catch{}
const symbols={galaxy:'<circle cx="12" cy="12" r="3"/><ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-35 12 12)"/>',planet:'<circle cx="12" cy="12" r="7"/><ellipse cx="12" cy="12" rx="11" ry="3" transform="rotate(-25 12 12)"/>',empire:'<path d="M4 20h16M6 20V9l6-5 6 5v11M9 20v-6h6v6M4 9h16"/>',diplomacy:'<path d="m3 8 4-3 5 3 5-3 4 3-3 10-6 3-6-3Z M7 10l5 4 5-4M12 14v7"/>',journal:'<path d="M5 3h14v18H5ZM8 7h8M8 11h8M8 15h5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2 4 0 1 3 3 1 3 0 1 4-2 2v3l1 3-3 3-3-1h-3l-2 2-4-1 0-3-1-3-3-1V10l3-1 1-3 0-3Z"/>',save:'<path d="M4 3h13l4 4v14H3V3ZM7 3v6h9V3M7 21v-8h10v8"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 .5-1 1-1 3M12 18h.01"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',ship:'<path d="m12 2 5 9 4 7-9-3-9 3 4-7Zm0 13v7"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 1v5m0 12v5M1 12h5m12 0h5"/>',credits:'<circle cx="12" cy="12" r="8"/><path d="M15 8H10a2 2 0 0 0 0 4h4a2 2 0 0 1 0 4H9M12 6v12"/>',science:'<path d="M9 3h6M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3M7 15h10"/>',materials:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm-9 5 9 5 9-5M12 12v10"/>',fuel:'<path d="M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z"/>',orders:'<path d="m4 7 3 3 5-6M4 17l3 3 5-6M14 8h7m-7 10h7"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',reset:'<path d="M4 9a8 8 0 1 1 0 7M4 3v6h6"/>'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${symbols[name]||symbols.target}</svg>`;}
function btn(label,action,opts={}){return `<button class="btn ${opts.primary?'primary':''} ${opts.small?'small':''} ${opts.danger?'danger':''}" data-action="${action}" ${opts.data||''} ${opts.disabled?'disabled':''}>${opts.icon?icon(opts.icon):''}${label}</button>`;}
function enabled(a){return !busy&&actionAvailability(state,a).available;}
function gameButton(label,a,options={}){return btn(label,'command',{...options,data:`data-command="${esc(JSON.stringify(a))}"`,disabled:!enabled(a)});}
function persist(){try{const old=localStorage.getItem(KEY+'.auto');if(old){const previous=validateSave(JSON.parse(old));if(previous.id===state.id&&(previous.revision||0)>(state.revision||0)){state=previous;toast('A newer save was loaded from another tab. Please repeat your last action.');return false;}localStorage.setItem(KEY+'.backup',old);}state.revision=(state.revision||0)+1;localStorage.setItem(KEY+'.auto',encodeSave(state));return true;}catch{toast('Device storage is unavailable or full. Export a save file to keep your campaign.');return false;}}
function toast(text){$('#toast').textContent=energyText(text);$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function apply(a){try{if(!state.operationalRules)initializeGalacticOperations(state);state=command(state,a);persist();render();sound();}catch(e){toast(e.message);}}
function sound(){if(!settings.sound)return;try{const ctx=new AudioContext();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.setValueAtTime(420,ctx.currentTime);gain.gain.setValueAtTime(.025,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.09);osc.start();osc.stop(ctx.currentTime+.1);osc.onended=()=>ctx.close();}catch{}}
function resourceBar(){const f=faction(state),inc=income(state);return `<div class="resources">${['credits','science','materials','fuel'].map(k=>`<div class="resource ${k}">${icon(k)}<span><span class="resource-label">${k}</span><strong>${f[k]}</strong><small>${k==='fuel'?'+2':k==='credits'?`${inc.credits-inc.upkeep>=0?'+':''}${inc.credits-inc.upkeep}`:`+${inc[k]}`} / round</small></span></div>`).join('')}</div>`;}
const navs=[['galaxy','Galaxy','galaxy'],['planets','Theatres','planet'],['civilization','Civilization','empire'],['diplomacy','Diplomacy','diplomacy'],['journal','Journal','journal']];
function renderView(){
 document.documentElement.dataset.motion=settings.motion?'on':'off';const f=faction(state),active=state.campaigns.filter(c=>c.attacker==='p'||c.defender==='p');
 $('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand" aria-label="Galactic Imperium home" data-action="view" data-view="galaxy"><img src="./assets/emblem.svg" alt=""><span>GALACTIC<br><b>IMPERIUM</b></span></a><div class="sidebar-label">COMMAND CENTER</div><nav aria-label="Main navigation">${navs.map(([id,label,i])=>`<button data-action="view" data-view="${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='planets'&&active.length?`<b class="count">${active.length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-badge"><span class="status-dot"></span> Solo · on your device</div><button class="nav-item" data-action="saves">${icon('save')}<span>Save & load</span></button><button class="nav-item" data-action="help">${icon('help')}<span>Field manual</span></button><button class="nav-item" data-action="settings">${icon('settings')}<span>Preferences</span></button><div class="version">SITUATION ROOM / v0.3.1</div></div></aside>
 <div class="workspace"><header class="topbar"><div class="mobile-brand"><img src="./assets/emblem.svg" alt=""><b>GALACTIC IMPERIUM</b></div><div class="breadcrumb">Galactic Imperium <span>/</span> <strong>The Situation Room</strong></div><div class="top-actions"><span class="saved-label"><span class="status-dot"></span> Local campaign</span><button class="icon-button" data-action="saves" aria-label="Save and load">${icon('save')}</button><button class="avatar" data-action="settings" aria-label="Preferences">MC</button></div></header>
 <main id="main" tabindex="-1"><div class="page-heading"><div><div class="eyebrow"><span class="status-dot"></span> ${esc(state.name)} <span class="tag">SOLO CAMPAIGN</span></div><h1>${({galaxy:'The situation room',planets:'Planetary operations',civilization:'Build your legacy',diplomacy:'A galaxy of interests',journal:'Command journal'})[view]}</h1><p class="subtitle">${({galaxy:'Every world is a decision. Every decision has consequences.',planets:'Win the orbit. Secure the beachhead. Hold the world.',civilization:'Shape the science, industry, and fleets behind your ambition.',diplomacy:'Some borders are drawn with fleets. Others with an agreement.',journal:'Your civilization’s story, one operation at a time.'})[view]}</p></div><div class="round-badge"><span>CAMPAIGN ROUND</span><strong>${String(state.round).padStart(2,'0')}<small> / ${state.maxRounds}</small></strong><span class="round-phase">${state.result?'Campaign complete':busy?'Resolving operations…':'Planning phase'}</span></div></div>
 ${resourceBar()}
 ${state.result?`<div class="result-banner">${icon('target')}<div><strong>${faction(state,state.result.winner).name} prevails</strong><p>Final prestige: ${state.result.ranking.map(r=>`${esc(faction(state,r.id).short)} ${r.score}`).join(' · ')}. Your campaign is saved.</p></div>${btn('New campaign','new',{primary:true})}</div>`:''}
 ${view==='galaxy'?galaxyView():view==='planets'?planetsView():view==='civilization'?civilizationView():view==='diplomacy'?diplomacyView():journalView()}
 <footer class="command-footer"><div>${icon('orders')}<span><strong>${f.actions} actions remaining</strong><small>${active.length} active theatre${active.length===1?'':'s'} · ${f.reserves} reserve cohorts</small></span></div><button class="btn small spend-actions" data-action="spend-actions" ${busy||state.result?'disabled':''}>Spend actions</button><button class="btn primary resolve" data-action="resolve" ${busy||state.result?'disabled':''}>${busy?'Resolving…':'Resolve round'} ${icon('arrow')}</button></footer>
 <div class="build-note">${practice?'PRACTICE SAVE · ':''}Original sci-fi rules · Playable alpha · <button data-action="scope">Development & rules coverage</button> · <a href="./full/campaign.html?v=0.3.1">New planetary campaign</a></div>
 </main><nav class="mobile-nav" aria-label="Mobile navigation">${navs.map(([id,label,i])=>`<button data-action="view" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${id==='civilization'?'Empire':label}</span></button>`).join('')}</nav></div>`;
 bindMap();
}
function galaxyView(){const f=faction(state);return `<div class="strategic-strip"><div class="strip-icon">${icon('target')}</div><div><span class="eyebrow">YOUR NEXT MOVE</span><strong>${moveFrom?moveKind==='raid-convoy'?'Select an enemy convoy destination':'Select a destination for your fleet':!f.priority?'Set your strategic priority':state.stats.conquests?'Consolidate your foothold':'Secure your first planetary foothold'}</strong><span>${moveFrom?'Orders spend one action and execute in initiative order when you resolve the round.':'Survey a frontier, commit your expedition, and turn ambition into territory.'}</span></div>${btn(moveFrom?'Cancel movement':'Strategic priorities',moveFrom?'cancel-move':'priorities',{small:true,icon:moveFrom?'close':'chevron'})}</div>
 ${operationsPanel()}<div class="galaxy-layout"><section class="panel map-panel"><div class="panel-heading"><div><h2>${icon('galaxy')} Galactic map</h2><span>THE HELION EXPANSE · SEED ${esc(state.seed)}</span></div><div class="map-tools"><button class="icon-button" data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><span data-map-zoom aria-label="Map zoom">${Math.round(zoom*100)}%</span><button class="icon-button" data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button class="icon-button" data-action="zoom-reset" aria-label="Reset zoom">${icon('reset')}</button></div></div><div class="map-scroll galactic-touch-map" aria-label="Galactic map. Pinch to zoom, drag to pan, tap a sector to inspect."><div class="map-canvas" style="width:${zoom*100}%">${galaxyMap()}</div></div><div class="map-touch-hint">Pinch to zoom · Drag to pan · Tap a sector to inspect</div><div class="map-legend"><span><i style="background:var(--teal)"></i> Meridian Accord</span><span><i style="background:var(--coral)"></i> Vesper</span><span><i style="background:var(--purple)"></i> Orison</span><span><i class="neutral"></i> Independent</span><span>◇ Transit relay</span><span>▥ Yard / pending vessels</span><span>Dashed lines: convoys & orders</span></div></section><aside class="inspector">${sectorInspector()}</aside></div>
 <div class="lower-grid">${mandatesCard()}<section class="panel dispatch"><div class="panel-heading"><h2>${icon('journal')} Latest dispatches</h2><button class="text-button" data-action="view" data-view="journal">View all ${icon('chevron')}</button></div>${state.log.slice(0,3).map(entry=>`<div class="dispatch-row"><span class="dispatch-dot ${entry.type}"></span><div><p>${esc(entry.text)}</p><small>ROUND ${String(entry.round).padStart(2,'0')}</small></div></div>`).join('')}</section></div>`;}
function hexPoints(cx,cy,r){return Array.from({length:6},(_,i)=>{const a=(60*i-30)*Math.PI/180;return `${cx+r*Math.cos(a)},${cy+r*Math.sin(a)}`;}).join(' ');}
function mapDefs(){return `<defs><radialGradient id="space"><stop stop-color="#1b263d"/><stop offset="1" stop-color="#101621"/></radialGradient>${[['Teal','#b5e1e6','#3f9ba5','#101e30'],['Coral','#ffccad','#ce7972','#331f38'],['Purple','#d4c1f0','#8474b8','#24243d'],['Gold','#e7d5ad','#9a8a63','#343339']].map(([n,a,b,c])=>`<radialGradient id="planet${n}" cx="30%" cy="25%"><stop stop-color="${a}"/><stop offset=".4" stop-color="${b}"/><stop offset="1" stop-color="${c}"/></radialGradient>`).join('')}</defs>`;}
function galaxyMap(){const size=47,cx=390,cy=315;const points=x=>({x:cx+Math.sqrt(3)*size*(x.q+x.r/2),y:cy+size*1.5*x.r});return `<svg class="galaxy-svg" viewBox="50 30 680 565" role="group" aria-label="Helion Expanse hex map">${mapDefs()}<rect x="50" y="30" width="680" height="565" fill="url(#space)"/>${Array.from({length:95},(_,i)=>`<circle cx="${60+(i*137)%660}" cy="${35+(i*83)%545}" r="${i%7===0?1.3:.65}" fill="#9aaed0" opacity="${i%3===0?.55:.2}"/>`).join('')}<text x="80" y="64" class="map-coordinate">HELION EXPANSE / DEEP FIELD 07</text>${state.sectors.map(x=>{const p=points(x),visible=x.revealed,color=x.owner?FACTIONS.find(f=>f.id===x.owner)?.color:'#788398',fl=x.fleets.p;const valid=moveFrom&&enabled({type:moveKind,from:moveFrom,sector:x.id});const sel=selected===x.id;const planet=x.owner==='p'?'Teal':x.owner==='r'?'Coral':x.owner==='v'?'Purple':'Gold';return `<g class="sector ${visible?'visible':'unexplored'} ${sel?'selected':''} ${valid?'reachable':''}" role="button" tabindex="0" aria-label="${visible?esc(x.name):'Uncharted sector'}${sel?', selected':''}" data-sector="${esc(x.id)}"><polygon points="${hexPoints(p.x,p.y,size-2)}" fill="${sel?'#283444':visible?(x.owner?color+'12':'#192234'):'#111925'}" stroke="${sel?'#e5d8ac':valid?'#5ed6ca':visible?color+'55':'#2c3546'}" stroke-width="${sel?2:1}"/>${visible?`<circle cx="${p.x}" cy="${p.y-7}" r="${x.home?17:x.inhabited?13:9}" fill="url(#planet${planet})"/>${x.home?`<ellipse cx="${p.x}" cy="${p.y-7}" rx="24" ry="7" fill="none" stroke="${color}" stroke-width="1" transform="rotate(-24 ${p.x} ${p.y-7})" opacity=".7"/>`:''}<text x="${p.x}" y="${p.y+19}" text-anchor="middle" class="sector-name">${esc(x.name.length>14?x.name.slice(0,12)+'…':x.name)}</text>${fl?.ships?`<rect x="${p.x-19}" y="${p.y+24}" width="38" height="14" rx="4" fill="#244e50"/><text x="${p.x}" y="${p.y+34}" text-anchor="middle" class="fleet-count">▲ ${fl.ships} · ${fl.troops}</text>`:x.owner?`<circle cx="${p.x}" cy="${p.y+29}" r="2" fill="${color}"/>`:''}${state.campaigns.some(c=>c.sector===x.id)?`<text x="${p.x+22}" y="${p.y-19}" fill="#efbc76" font-size="16">⚑</text>`:''}`:`<text x="${p.x}" y="${p.y+4}" text-anchor="middle" class="unknown-symbol">+</text>`}</g>`;}).join('')}${galacticMapOverlays(points)}<text x="80" y="569" class="map-coordinate">TAP TO INSPECT · ▲ VESSELS / EMBARKED COHORTS</text></svg>`;}
function sectorInspector(){const x=sector(state,selected),fl=x.fleets.p;const owner=FACTIONS.find(f=>f.id===x.owner);const campaign=state.campaigns.find(c=>c.sector===x.id);if(!x.revealed)return `<section class="panel"><div class="inspector-body"><span class="eyebrow">OUTSIDE SENSOR RANGE</span><h2>Uncharted space</h2><p>Survey frontier sectors or move a fleet to extend your visibility.</p></div></section>`;
return `<section class="panel sector-detail"><div class="planet-art ${x.biome.toLowerCase()}"><span class="planet-orbit"></span><span class="planet-sphere"></span><span class="sector-tag">${x.home?'HOME SYSTEM':x.inhabited?'INHABITED WORLD':'FRONTIER WORLD'}</span><span class="coordinate">${x.q>=0?'+':''}${x.q} / ${x.r>=0?'+':''}${x.r}</span></div><div class="inspector-body"><div class="eyebrow">SECTOR INTELLIGENCE</div><h2>${esc(x.name)} ${x.owner==='p'?'<span class="tiny-dot"></span>':''}</h2><div class="world-subtitle">${esc(x.biome)} · ${owner?esc(owner.name):'Independent space'}</div><div class="detail-stats"><div><span>Surface</span><strong>${x.occupation?'Occupied':x.owner==='p'?'Secure':x.discovered?`${x.garrison} defenders`:'Unsurveyed'}</strong></div><div><span>Orbit</span><strong>${x.orbit?esc(faction(state,x.orbit)?.short||'Independent'):'Uncontested'}</strong></div></div><div class="yield-row">${['credits','science','materials'].map(k=>`<span>${icon(k)} ${x.income[k]}</span>`).join('')}<span class="muted">base yield</span></div>${fl?.ships?`<div class="fleet-summary">${icon('ship')}<div><strong>Expeditionary fleet</strong><small>${fl.ships} vessels · ${fl.troops} embarked cohorts</small></div></div>`:''}<div class="action-stack">${gameButton('Survey sector',{type:'explore',sector:x.id},{icon:'target'})}${fl?.ships?btn('Plot fleet move','move',{primary:true,icon:'arrow',data:`data-from="${esc(x.id)}"`,disabled:busy||!faction(state).actions||fleetCommitted(state,'p',x.id)}):''}${fl?.ships?btn('Plan convoy raid','raid',{small:true,data:`data-from="${esc(x.id)}"`,disabled:busy||!faction(state).actions||fleetCommitted(state,'p',x.id)}):''}${!x.owner&&(!x.inhabited||!x.garrison)?gameButton('Establish colony',{type:'colonize',sector:x.id},{primary:true}):''}${!campaign&&x.owner!=='p'&&x.inhabited?gameButton('Launch invasion',{type:'invade',sector:x.id},{primary:true,icon:'planet'}):''}${campaign?btn('Open planetary campaign','campaign',{primary:true,icon:'planet',data:`data-id="${esc(campaign.id)}"`}):''}${x.owner==='p'?`<div class="action-pair">${gameButton('Build vessel',{type:'build',sector:x.id,unit:'ship'},{small:true})}${gameButton('Embark troops',{type:'load',sector:x.id},{small:true})}</div>`:''}</div>${galacticInfrastructure(x)}<p class="microcopy">${x.owner==='p'?'Vessels cost 5 materials + 1 credit at the standard blueprint and deploy at upkeep. Each order uses one action. Plotting movement reserves its fuel.':x.inhabited?'Surface control requires a successful invasion. Bring at least 2 cohorts and secure orbit first.':'A fleet and a settlement investment establish control.'}</p></div></section>`;}
function mandatesCard(){return `<section class="panel mandates"><div class="panel-heading"><h2>${icon('target')} Galactic mandates</h2><span class="tag">${state.scored.filter(x=>x!=='ambition').length}/4</span></div>${[['explorer','Frontier cartographer','Survey 3 frontier sectors',state.stats.explored,3,2],['scholar','Scientific ascendancy','Research 3 technologies',faction(state).tech.length,3,2],['conqueror','A foothold among stars','Successfully invade a defended world',state.stats.conquests,1,3],['diplomat','Accord of civilizations','Maintain a nonaggression agreement',state.treaties.some(t=>t.parties.includes('p'))?1:0,1,1]].map(([id,name,desc,n,max,score])=>`<div class="mandate-row"><span class="mandate-icon ${state.scored.includes(id)?'complete':''}">${icon(state.scored.includes(id)?'check':'target')}</span><div><strong>${name}</strong><small>${desc}</small><div class="progress"><span style="width:${Math.min(100,n/max*100)}%"></span></div></div><b>+${score}</b></div>`).join('')}</section>`;}
function planetsView(){const all=state.campaigns.filter(c=>c.attacker==='p'||c.defender==='p');const c=all.find(c=>c.id===campaignId)||all[0];if(c){campaignId=c.id;return `<div class="theatre-tabs">${all.map(v=>btn(esc(v.name),'campaign',{primary:v.id===c.id,data:`data-id="${esc(v.id)}"`})).join('')}</div>${groundView(c)}`;}return `<section class="panel empty-theatre"><div class="empty-orbit">${icon('planet')}</div><div class="eyebrow">NO ACTIVE PLANETARY CAMPAIGNS</div><h2>The next frontier is below.</h2><p>Move an expeditionary fleet to a defended world, secure its orbit, and launch an invasion. Your landing will open a persistent operational hex map.</p><div class="steps"><span><b>01</b> Embark troops</span><span><b>02</b> Secure orbit</span><span><b>03</b> Commit the landing</span></div>${btn('Return to the galaxy','view',{primary:true,icon:'arrow',data:'data-view="galaxy"'})}</section><div class="lower-grid">${mandatesCard()}<section class="panel guide-card"><span class="eyebrow">INVASION BRIEFING</span><h2>Winning orbit is only the beginning.</h2><p>Supply enters through the landing port. Capture the capital and hold it through two operations while breaking resistance. Surface campaigns resolve twice per galactic round.</p><p>A quick route to your first landing: embark troops at Meridian Prime, move to adjacent Pelagos, and launch an invasion.</p>${btn('Read the field manual','help',{icon:'help'})}</section></div>`;}
function groundView(c){if(c.operational)return worldCampaignView(c);const side=c.attacker==='p'?'a':'d',src=c.tiles.find(t=>t.id===groundSelected),enemy=side==='a'?'d':'a';const orders=c.orders.filter(o=>o.side===side);return `<div class="strategic-strip"><div class="strip-icon">${icon('planet')}</div><div><span class="eyebrow">${side==='a'?'EXPEDITIONARY COMMAND':'PLANETARY DEFENSE'} · OPERATION ${c.cycle+1}</span><strong>${esc(c.name)} campaign</strong><span>Select a formation, choose an order, then tap its target region.</span></div>${gameButton('Supply +5',{type:'supply',campaign:c.id},{small:true})}</div><div class="operation-stats"><div><span>Our morale</span><strong>${c.morale[side]}<small> / 10</small></strong></div><div><span>Enemy morale</span><strong>${c.morale[enemy]}<small> / 10</small></strong></div><div><span>Supplies</span><strong>${c.supply[side]}</strong></div><div><span>Orders queued</span><strong>${orders.length}<small> / ${3+(faction(state).tech.includes('doctrine')?1:0)}</small></strong></div></div><div class="galaxy-layout"><section class="panel map-panel"><div class="panel-heading"><h2>${icon('planet')} Surface operations</h2><span class="tag">SIMULTANEOUS ORDERS</span></div><div class="ground-map">${groundMap(c,side)}</div><div class="map-legend"><span><i style="background:var(--teal)"></i> Friendly</span><span><i style="background:var(--coral)"></i> Hostile</span><span>▲ Formation strength</span><span>→ Planned advance</span></div></section><aside><section class="panel inspector-body"><div class="eyebrow">OPERATIONAL ORDERS</div><h2>${src?esc(src.site||src.terrain+' region'):'Select a formation'}</h2><p>${src?`${src.units} formation${src.units===1?'':'s'} · ${src.owner===side?'Friendly control':'Hostile control'} · ${src.terrain}`:'Tap a hex containing your troops to begin planning.'}</p><label class="field-label" for="ground-order">Order type</label><select id="ground-order">${[['advance','Advance / assault'],['defend','Defend / entrench'],['support','Support attack'],['bombard','Strategic strike'],['raid','Raid supply'],['orbital','Orbital strike · 2 fuel']].map(([v,l])=>`<option value="${v}" ${v===groundType?'selected':''}>${l}</option>`).join('')}</select><p class="microcopy">${groundType==='advance'?'Advance into an adjacent hex, leaving one formation as a garrison when possible. Enemy orders remain hidden until resolution.':groundType==='defend'?'Select your formation again to queue a defensive posture.':groundType==='orbital'?'Select a hostile region. Requires orbit, 2 fuel, and one command action; damages infrastructure.':'Select a target within 2 hexes. Support weakens resistance; raids reduce supplies.'}</p>${src?gameButton('Cancel this order',{type:'cancel-ground',campaign:c.id,from:src.id},{small:true}):''}<div class="order-list">${orders.length?orders.map(o=>`<div><b>${esc(o.type)}</b><span>Region ${Number(o.from)+1} → ${Number(o.to)+1}</span></div>`).join(''):'<span class="muted">No orders committed.</span>'}</div>${gameButton('Evacuate expedition',{type:'withdraw',campaign:c.id},{danger:true,small:true})}</section></aside></div><section class="panel roster"><div class="panel-heading"><h2>${icon('ship')} Local reinforcement</h2><span>Uses materials + 1 credit and one command action</span></div><div class="unit-grid">${UNITS.map(u=>`<div class="unit-card"><span class="eyebrow">${u.domain}</span><strong>${u.name}</strong><small>${u.role}</small>${gameButton(`Deploy · ${u.cost} materials`,{type:'recruit-ground',campaign:c.id,unit:u.id},{small:true})}</div>`).join('')}</div></section>`;}
function groundMap(c,side){const coords=t=>({x:330+Math.sqrt(3)*51*(t.q+t.r/2),y:245+51*1.5*t.r});return `<svg viewBox="65 35 530 420" class="ground-svg" role="group" aria-label="Planetary hex battlefield">${mapDefs()}<rect x="65" y="35" width="530" height="420" fill="url(#space)"/>${c.tiles.map(t=>{const p=coords(t),own=t.owner===side,col=own?'#5ed6ca':'#ee627b';return `<g role="button" tabindex="0" aria-label="Region ${Number(t.id)+1}, ${t.site||t.terrain}, ${own?'friendly':'hostile'}, ${t.units} formations" data-ground="${t.id}" class="ground-hex ${t.id===groundSelected?'selected':''}"><polygon points="${hexPoints(p.x,p.y,49)}" fill="${t.terrain==='Ocean'?'#172c42':own?'#1d383b':'#392830'}" stroke="${t.id===groundSelected?'#e5d8ac':col+'60'}" stroke-width="${t.id===groundSelected?3:1}"/><text x="${p.x}" y="${p.y-15}" text-anchor="middle" class="ground-site">${t.site||t.terrain}</text><text x="${p.x}" y="${p.y+7}" text-anchor="middle" class="ground-strength" fill="${col}">${t.units?'▲ '+t.units:'·'}</text><text x="${p.x}" y="${p.y+27}" text-anchor="middle" class="ground-number">${String(Number(t.id)+1).padStart(2,'0')}</text></g>`;}).join('')}${c.orders.filter(o=>o.side===side&&o.type==='advance').map(o=>{const a=coords(c.tiles.find(t=>t.id===o.from)),b=coords(c.tiles.find(t=>t.id===o.to));return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#f1d6a2" stroke-width="3" stroke-dasharray="5 4" pointer-events="none"/>`;}).join('')}</svg>`;}
function civilizationView(){const f=faction(state),inc=income(state);return `<div class="empire-summary panel"><div class="civilization-seal">${icon('empire')}</div><div><span class="eyebrow">YOUR CIVILIZATION</span><h2>Meridian Accord</h2><p>Curiosity is our compass. Resolve is our shield.</p></div><div class="summary-values"><span><b>${colonies(state).length}</b> worlds</span><span><b>${fleets(state).reduce((n,x)=>n+x.fleets.p.ships,0)}</b> vessels</span><span><b>${f.score}</b> prestige</span></div></div><div class="tabs"><button class="${tab==='research'?'active':''}" data-action="empire-tab" data-tab="research">Research</button><button class="${tab==='shipyard'?'active':''}" data-action="empire-tab" data-tab="shipyard">Ship design</button><button class="${tab==='economy'?'active':''}" data-action="empire-tab" data-tab="economy">Economy & production</button></div>${tab==='research'?`<div class="card-grid">${TECHS.map(t=>`<section class="panel technology ${f.tech.includes(t.id)?'researched':''}"><div class="tech-icon">${icon(t.category==='Warfare'?'target':t.category==='Industry'?'materials':'science')}</div><span class="eyebrow">${t.category}</span><h2>${t.name}</h2><p>${t.desc}</p>${f.tech.includes(t.id)?'<div class="researched-label">'+icon('check')+' RESEARCHED</div>':gameButton(`Research · ${Math.max(1,t.cost-1)} science`,{type:'research',id:t.id},{small:true})}</section>`).join('')}</div>`:tab==='shipyard'?`<div class="lower-grid"><section class="panel blueprint"><div class="eyebrow">FLEET BLUEPRINT / UNIVERSAL HULL</div><h2>Design the next expedition</h2><div class="ship-illustration"><svg viewBox="0 0 360 200" aria-label="Original spacecraft illustration"><path d="m180 12 30 78 65 55-65-10-30 50-30-50-65 10 65-55Z" fill="#334553" stroke="#80b5b8" stroke-width="2"/><path d="m180 35 12 70-12 40-12-40Z" fill="#5ed6ca" opacity=".7"/><path d="m150 135-15 34m75-34 15 34" stroke="#efbc76" stroke-width="6"/></svg></div><form id="blueprint-form"><label>Weapons <select name="weapon"><option value="1" ${f.blueprint.weapon===1?'selected':''}>Standard lances · 1 slot</option><option value="2" ${f.blueprint.weapon===2?'selected':''}>Plasma lances · 2 slots (research)</option></select></label><label>Defense <select name="shield"><option value="0" ${!f.blueprint.shield?'selected':''}>Unshielded · 0 slots</option><option value="1" ${f.blueprint.shield?'selected':''}>Phase shield · 1 slot (research)</option></select></label><label>Transport <select name="transport">${[1,2,3].map(n=>`<option value="${n}" ${f.blueprint.transport===n?'selected':''}>${n} cohort${n===1?'':'s'} / vessel · ${n} slots</option>`).join('')}</select></label><p class="microcopy">5 component slots available. Refitting costs 2 materials and 1 command action. Existing embarked troops must fit the new design.</p><button class="btn primary" ${!f.actions?'disabled':''}>Commit blueprint</button></form></section><section class="panel guide-card"><span class="eyebrow">DOCTRINE & DESIGN</span><h2>Every component is a commitment.</h2><p>Transport capacity gets your armies to the surface. Weapons win access to orbit. Shielding protects the investment.</p><div class="detail-stats"><div><span>Current slots</span><strong>${f.blueprint.weapon+f.blueprint.shield+f.blueprint.transport} / 5</strong></div><div><span>Build cost</span><strong>${4+f.blueprint.weapon+f.blueprint.shield} materials</strong></div></div><p>Your blueprint applies to the civilization’s fleets. Research unlocks stronger components; it does not install them automatically.</p></section></div>`:`<div class="lower-grid"><section class="panel inspector-body"><span class="eyebrow">ROUND PROJECTION</span><h2>A sustainable civilization</h2><div class="economy-table">${['credits','science','materials'].map(k=>`<div><span>${icon(k)} ${k}</span><strong>+${inc[k]}</strong></div>`).join('')}<div><span>Administration & fleet upkeep</span><strong>−${inc.upkeep} credits</strong></div><div><span>Net credits</span><strong>${inc.credits-inc.upkeep>=0?'+':''}${inc.credits-inc.upkeep}</strong></div></div><p class="microcopy">Occupied worlds produce at half rate. Damage reduces output. A deficit reduces your next round’s command capacity.</p></section><section class="panel inspector-body"><span class="eyebrow">PRODUCTION SITES</span><h2>Colonial infrastructure</h2>${colonies(state).map(x=>`<div class="colony-row"><div><strong>${esc(x.name)}</strong><small>${x.occupation?`${x.occupation} rounds to stabilize`:`Shipyard ${Math.max(0,yardCapacity(x)-state.shipConstruction.filter(q=>q.sector===x.id).length)}/${yardCapacity(x)} slots · ${state.shipConstruction.filter(q=>q.sector===x.id).length} pending`}</small></div><div>${gameButton('Queue vessel',{type:'build',sector:x.id,unit:'ship'},{small:true})}${gameButton('Cohorts',{type:'build',sector:x.id,unit:'troops'},{small:true})}${x.damage?gameButton('Repair',{type:'build',sector:x.id,unit:'repair'},{small:true}):''}</div></div>`).join('')}</section></div>`}`;}
function diplomacyView(){return `<div class="diplomacy-grid">${state.factions.filter(f=>f.id!=='p').map(f=>`<section class="panel faction-card"><div class="faction-banner" style="--faction:${f.color}"><div class="faction-emblem">${icon('empire')}</div><span>${f.short}</span></div><div class="inspector-body"><span class="eyebrow">${esc(f.style)}</span><h2>${esc(f.name)}</h2><div class="relationship"><span class="status-dot" style="background:${f.relations<-2?'var(--coral)':'var(--teal)'}"></span>${isTreaty(state,'p',f.id)?'Nonaggression agreement active':f.relations<-2?'Hostile relations':f.relations>1?'Warm relations':'Open diplomatic channels'}</div><p>${esc(f.bonus)}</p><div class="action-stack">${gameButton('Propose nonaggression · 3 credits',{type:'treaty',with:f.id},{icon:'diplomacy'})}${gameButton('Mutual transit · 2 credits',{type:'transit',with:f.id},{small:true})}${gameButton('Buy 3 materials · 4 credits',{type:'trade',with:f.id})}${gameButton('Offer reparations · 3 credits',{type:'gift',with:f.id},{small:true})}</div></div></section>`).join('')}<section class="panel assembly"><span class="eyebrow">GALACTIC ASSEMBLY · PROPOSAL ${state.agenda+1}</span><h2>${LAWS[state.agenda].name}</h2><p>${LAWS[state.agenda].desc}</p><div class="vote-summary">Your delegation has <strong>${Math.max(1,colonies(state).length)+(faction(state).priority==='diplomacy'?2:0)} votes</strong>.</div><div class="action-pair">${gameButton('Vote for',{type:'vote',vote:'for'},{primary:state.vote==='for'})}${gameButton('Vote against',{type:'vote',vote:'against'},{primary:state.vote==='against'})}</div><p class="microcopy">${state.vote?`Ballot committed: ${state.vote}.`:'Abstaining casts no votes for the proposal.'} Rival delegates resolve their votes at the round boundary.</p><div class="law-status">${state.law?`Active law: ${LAWS.find(l=>l.id===state.law).name}`:'No active galactic law.'}</div></section></div><div class="lower-grid">${mandatesCard()}<section class="panel inspector-body"><span class="eyebrow">PRIVATE AMBITION · +3 PRESTIGE</span><h2>${({exploration:'Survey six frontier sectors',science:'Research five technologies',fleet:'Maintain seven vessels'})[state.ambition||'science']}</h2><p>${state.scored.includes('ambition')?'Ambition achieved. Prestige awarded.':'This objective belongs to your civilization. It is scored once at the round boundary.'}</p><hr><span class="eyebrow">SPECIAL OPERATIONS</span><h2>A reserve of possibilities</h2><p>One-use interventions provide bounded support without spending a command action.</p><div class="action-stack">${gameButton('Emergency resupply · +4 fuel, +2 cohorts',{type:'intervention',id:'resupply'},{icon:'fuel'})}${gameButton('Deep reconnaissance · scan selected sector',{type:'intervention',id:'intel',sector:selected},{icon:'target'})}</div><p class="microcopy">${state.interventions.length} interventions remaining. Reconnaissance targets the sector selected on the galaxy map.</p></section></div>`;}
function journalView(){return `<section class="panel journal-panel"><div class="panel-heading"><h2>${icon('journal')} Campaign history</h2><span>${state.log.length} retained events · newest first</span></div>${state.log.map(e=>`<div class="journal-entry"><div class="journal-round">R${String(e.round).padStart(2,'0')}</div><span class="dispatch-dot ${e.type}"></span><div><span class="eyebrow">${esc(e.type)}</span><p>${esc(e.text)}</p></div></div>`).join('')}</section>`;}
function showDialogView(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){$('#dialog').close();}
function savesDialog(){const slots=read(KEY+'.slots',{});showDialog('Your campaigns',`<p class="dialog-intro">Autosaved on this browser after each command. Export a file to keep a portable copy on your computer or phone.</p><div class="save-auto"><span class="status-dot"></span><div><strong>Current campaign · round ${state.round}</strong><small>${esc(state.name)} / ${esc(state.seed)}</small></div>${btn('Save now','save-now',{small:true})}</div><div class="save-slots">${[1,2,3].map(i=>`<div class="save-slot"><span class="slot-number">0${i}</span><div><strong>${slots[i]?esc(slots[i].name):'Empty save slot'}</strong><small>${slots[i]?`Round ${slots[i].round} · ${new Date(slots[i].savedAt).toLocaleString()}`:'Available on this device'}</small></div>${btn('Save','save-slot',{small:true,data:`data-slot="${i}"`})}${btn('Load','load-slot',{small:true,data:`data-slot="${i}"`,disabled:!slots[i]})}</div>`).join('')}</div><div class="action-pair">${btn('Export save file','export',{icon:'download',primary:true})}${btn('Import save file','import',{icon:'upload'})}</div><p class="microcopy">Browser data can be cleared by the device. Export files are independent backups. Imported saves are validated before loading.</p><hr><div class="action-pair">${btn('Restore automatic backup','restore-backup',{icon:'reset',disabled:!read(KEY+'.backup',null)})}${btn('Start a new campaign','new',{icon:'plus'})}</div>`);}
function newDialog(){showDialog('A new beginning',`<p class="dialog-intro">Lead the Meridian Accord against two AI civilizations. Your existing autosave can be kept in a save slot first.</p><form id="new-form"><label>Campaign name<input name="name" maxlength="60" value="The first frontier" required></label><label>Galaxy seed<input name="seed" maxlength="40" value="DAWN-${String(Math.floor(Math.random()*999)).padStart(3,'0')}" required></label><div class="form-pair"><label>Campaign length<select name="rounds"><option value="8">8 rounds · short</option><option value="12" selected>12 rounds · standard</option><option value="20">20 rounds · extended</option></select></label><label>Difficulty<select name="difficulty"><option value="relaxed">Relaxed</option><option value="standard" selected>Standard</option><option value="veteran">Veteran</option></select></label></div><p class="microcopy">Standard uses equal starting resources. Relaxed grants you additional supplies; Veteran grants AI civilizations additional starting industry. No difficulty reveals your hidden ground orders to rivals.</p><button class="btn primary" type="submit">Establish command ${icon('arrow')}</button></form>`);}
const lessons=[['Welcome, Commander','You lead the Meridian Accord. This is a turn-based solo campaign: nothing advances while you are away. Your first goal is a foothold on a defended frontier world.'],['Prepare your expedition','Select Meridian Prime and embark troops. Each vessel carries 2 cohorts with the standard blueprint. You begin with 5 cohorts aboard and 9 in reserve. Build additional vessels or recruit reserves in Civilization.'],['Survey and move','Survey an adjacent sector to learn about it and reveal nearby space. Choose Plot fleet move, then tap an adjacent destination. Plot a move toward Pelagos, an independent defended world, then resolve the round to execute it. Fuel bids determine initiative.'],['Land and command','With orbit secured and at least 2 cohorts aboard, launch an invasion. In Theatres, open the province campaign. Select command stacks, plot adjacent hex routes, and seal orders. Movement follows initiative. Complete two operational cycles per galactic round.'],['Supply and surrender','Capture provinces and industry to fund local production. Deliver energy, alloy, materiel, or embarked troops from orbit. Secure opposing regional capitals to win the planetary campaign; ownership changes when the galactic round resolves.'],['Plan the wider campaign','Adopt one strategic priority each round, research technology, negotiate treaties, and vote in the assembly. Resolve round to advance AI civilizations, settle completed planetary cycles, and collect income.'],['Keep your campaign','Use Save & load for three local save slots and downloadable JSON saves. Final prestige includes earned points, secure worlds, and technology. The development panel lists current rules coverage.']];
function helpDialog(){const [title,body]=lessons[tutorialStep];showDialog('Field manual',`<div class="tutorial-count">COMMAND ORIENTATION · ${tutorialStep+1} / ${lessons.length}</div><div class="tutorial-icon">${icon(['galaxy','ship','target','planet','fuel','diplomacy','save'][tutorialStep])}</div><h3>${title}</h3><p class="tutorial-text">${body}</p><div class="tutorial-dots">${lessons.map((_,i)=>`<span class="${i===tutorialStep?'active':''}"></span>`).join('')}</div><div class="action-pair">${btn('Previous','lesson-prev',{disabled:tutorialStep===0})}${btn(tutorialStep===lessons.length-1?'Return to command':'Next','lesson-next',{primary:true,icon:'arrow'})}</div>`);}
function scopeDialog(){showDialog('Development & rules coverage',`<span class="tag">DEVELOPMENT BUILD · v0.3.1</span><p>New invasions open a linked 127-hex province campaign with regional governments, seas, ports, industry, rails, differentiated units, command stacks, and seven operational phases. Complete two operational cycles per galactic round. Existing small-map invasions continue under their original rules.</p><p>Operational combat includes air and surface stages, strategic bombing, convoy raids, transport losses, garrisons, delayed production, territorial capture, and morale. Raid targets and standing priorities are selectable. Orbital fleets can deliver resources and embarked reinforcements.</p><p>The full adaptation is still in development. The galactic layer retains a simplified action economy, eight technologies, a universal fleet blueprint, and abstract space combat. Complete hull and technology catalogs, influence and population tracks, diplomacy/reputation, scenario victory rules, Quick Play, and the expanded political systems are unfinished. Passing regression tests does not establish complete source-game parity.</p><a class="btn" href="./docs/IMPLEMENTATION.md" target="_blank" rel="noopener">Read implementation status</a>`);}
function settingsDialog(){showDialog('Preferences',`<form id="settings-form"><label class="toggle-row"><span><strong>Interface motion</strong><small>Subtle transitions and atmospheric movement</small></span><input type="checkbox" name="motion" ${settings.motion?'checked':''}></label><label class="toggle-row"><span><strong>Command sounds</strong><small>Quiet feedback after successful commands</small></span><input type="checkbox" name="sound" ${settings.sound?'checked':''}></label><p class="microcopy">System reduced-motion preferences are respected. Preferences are stored on this device.</p><button class="btn primary">Save preferences</button></form><hr>${btn('New campaign','new',{icon:'plus'})}${btn('Field manual','help',{icon:'help'})}`);}
function bindMap(){galacticTouchMap?.destroy();galacticTouchMap=null;const galaxyViewport=document.querySelector('.galactic-touch-map');if(galaxyViewport)galacticTouchMap=bindTouchMap(galaxyViewport,{initialZoom:zoom,initialPosition:galaxyPosition,onZoom:value=>{zoom=value;},onPan:value=>{galaxyPosition=value;}});document.querySelectorAll('[data-sector],[data-ground]').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.dispatchEvent(new MouseEvent('click',{bubbles:true}));}}));$('#ground-order')?.addEventListener('change',e=>{groundType=e.target.value;render();});}
async function resolve(){if(busy||state.result)return;showDialog('Resolve this round?',`<p>Rivals will commit orders. Fleet operations execute in initiative order, convoy raids resolve, planetary campaigns run two operations, then shipbuilding, income, stability, and assembly votes resolve.</p><div class="save-auto"><div><strong>${faction(state).actions} unused command actions</strong><small>Unused actions do not carry over.</small></div></div><p class="microcopy">An automatic backup is kept before resolution.</p><div class="action-pair">${btn('Keep planning','close')}${btn('Commit & resolve','commit-round',{primary:true,icon:'arrow'})}</div>`);}
async function commitRound(){closeDialog();busy=true;render();try{const plans=await new Promise(resolve=>{if(!worker){resolve(planAI(state));return;}const timer=setTimeout(()=>resolve(planAI(state)),4000);worker.onmessage=e=>{clearTimeout(timer);resolve(e.data.plans||planAI(state));};worker.onerror=()=>{clearTimeout(timer);resolve(planAI(state));};worker.postMessage(state);});state=endRound(state,plans);persist();sound();toast(state.result?'Campaign concluded. Review the final council result.':`Round ${state.round}: new resources and orders available.`);}catch(e){toast(`Resolution stopped: ${e.message}`);}finally{busy=false;render();}}
document.addEventListener('click',async e=>{
 const hex=e.target.closest('[data-sector]');if(hex){if(moveFrom){try{state=command(state,{type:moveKind,from:moveFrom,sector:hex.dataset.sector});moveFrom=null;selected=hex.dataset.sector;persist();render();sound();}catch(err){toast(err.message);}return;}selected=hex.dataset.sector;render();return;}
 const ground=e.target.closest('[data-ground]');if(ground){const c=state.campaigns.find(c=>c.id===campaignId);if(!c)return;const side=c.attacker==='p'?'a':'d',dst=c.tiles.find(t=>t.id===ground.dataset.ground);if(groundType==='orbital'){apply({type:'orbital',campaign:c.id,to:dst.id});return;}if(groundSelected!==null){const src=c.tiles.find(t=>t.id===groundSelected);if(src?.owner===side&&src.units&&(src.id!==dst.id||groundType==='defend')){try{state=command(state,{type:'ground-order',campaign:c.id,from:src.id,to:dst.id,order:groundType});groundSelected=null;persist();render();toast('Operational order queued.');}catch(err){toast(err.message);}return;}}groundSelected=dst.id;render();return;}
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;if(el.tagName==='A')e.preventDefault();
 if(busy&&!['view','close','help','lesson-next','lesson-prev','scope'].includes(a)){toast('Wait for round resolution to finish.');return;}if(a==='open-world'){if(persist())location.href=el.dataset.href;return;}if(a==='command'){apply(JSON.parse(el.dataset.command));return;}if(a==='spend-actions'){spendActionsDialog();return;}if(a==='spend-choice'){try{state=command(state,JSON.parse(el.dataset.command));persist();render();spendActionsDialog();sound();}catch(error){toast(error.message);spendActionsDialog();}return;}
 if(a==='view'){view=el.dataset.view;moveFrom=null;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(a==='move'||a==='raid'){moveFrom=el.dataset.from;moveKind=a==='raid'?'raid-convoy':'move';toast(a==='raid'?'Select an adjacent enemy-owned convoy destination.':'Select a destination. The fleet moves when the round resolves.');render();return;}
 if(a==='cancel-move'){moveFrom=null;render();return;}
 if(a==='zoom-in'||a==='zoom-out'||a==='zoom-reset'){galacticTouchMap?.setZoom(a==='zoom-reset'?1:zoom+(a==='zoom-in'?.25:-.25));return;}
 if(a==='campaign'){view='planets';campaignId=el.dataset.id;groundSelected=null;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(a==='empire-tab'){tab=el.dataset.tab;render();return;}
 if(a==='resolve'){resolve();return;}if(a==='commit-round'){commitRound();return;}
 if(a==='close'){closeDialog();return;}if(a==='saves'){savesDialog();return;}if(a==='settings'){settingsDialog();return;}if(a==='new'){newDialog();return;}if(a==='scope'){scopeDialog();return;}
 if(a==='help'){tutorialStep=0;helpDialog();return;}if(a==='lesson-prev'){tutorialStep=Math.max(0,tutorialStep-1);helpDialog();return;}if(a==='lesson-next'){if(tutorialStep===lessons.length-1)closeDialog();else{tutorialStep++;helpDialog();}return;}
 if(a==='restore-backup'){try{pendingImport=validateSave(read(KEY+'.backup',null));showDialog('Restore automatic backup?',`<p>Restore ${esc(pendingImport.name)}, round ${pendingImport.round}? The current campaign becomes the next backup.</p>${btn('Cancel','saves')}${btn('Restore campaign','confirm-import',{primary:true})}`);}catch(err){toast('Backup is unavailable: '+err.message);}return;}
 if(a==='save-now'){if(persist())toast('Campaign saved on this device.');return;}
 if(a==='save-slot'){try{const slots=read(KEY+'.slots',{}),i=el.dataset.slot;if(slots[i]){showDialog('Replace save slot?',`<p>Slot ${i} contains ${esc(slots[i].name)}, round ${slots[i].round}. Replace it with your current campaign?</p>${btn('Cancel','saves')}${btn('Replace slot','confirm-save-slot',{primary:true,data:`data-slot="${i}"`})}`);return;}saveSlot(i);}catch{toast('Unable to save. Export a file instead.');}return;}
 if(a==='confirm-save-slot'){saveSlot(el.dataset.slot);return;}
 if(a==='load-slot'){const slots=read(KEY+'.slots',{}),slot=slots[el.dataset.slot];if(!slot)return;showDialog('Load saved campaign?',`<p>Load ${esc(slot.name)}, round ${slot.round}? Your current campaign will remain in the automatic backup.</p>${btn('Cancel','saves')}${btn('Load campaign','confirm-load-slot',{primary:true,data:`data-slot="${el.dataset.slot}"`})}`);return;}
 if(a==='confirm-load-slot'){try{state=initializeGalacticOperations(validateSave(read(KEY+'.slots',{})[el.dataset.slot].game));selected=state.sectors.find(x=>x.owner==='p')?.id||'-3,1';campaignId=null;persist();closeDialog();render();toast('Saved campaign loaded.');}catch(err){toast(err.message);}return;}
 if(a==='export'){const blob=new Blob([encodeSave(state)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`galactic-imperium-round-${state.round}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Save file prepared for download.');return;}
 if(a==='import'){$('#import-file').click();return;}
 if(a==='confirm-import'){state=initializeGalacticOperations(pendingImport);pendingImport=null;selected=state.sectors.find(x=>x.owner==='p')?.id||'-3,1';campaignId=null;persist();closeDialog();render();toast('Imported campaign loaded.');return;}
 if(a==='priorities'){showDialog('Set your strategic priority',`<p class="dialog-intro">Choose one program for this round. Benefits are immediate; another program becomes available next round.</p>${(state.offers||[]).length?'<div class="secondary-programs"><h3>Shared opportunities</h3><p>Optional offers from other civilizations. Each costs 2 credits.</p>'+(state.offers||[]).map(o=>btn('Gain 2 '+o.resource,'follow',{small:true,data:`data-id="${o.id}"`,disabled:!enabled({type:'follow',id:o.id})})).join('')+'</div>':''}<div class="priority-grid">${PRIORITIES.map(p=>`<div class="priority-card"><div class="tech-icon">${icon(p.id==='industry'?'materials':p.id==='science'?'science':p.id==='logistics'?'ship':'diplomacy')}</div><h3>${p.name}</h3><p>${p.desc}</p>${btn(faction(state).priority===p.id?'Committed':'Adopt program','choose-priority',{primary:true,small:true,data:`data-id="${p.id}"`,disabled:!!faction(state).priority||!!state.result})}</div>`).join('')}</div>`);return;}
 if(a==='follow'){apply({type:'follow',id:el.dataset.id});closeDialog();return;}
 if(a==='choose-priority'){apply({type:'priority',id:el.dataset.id});closeDialog();}
});

function operationsPanel(){const f=faction(state),orders=state.fleetOrders.filter(o=>o.owner==='p');return `<section class="panel galactic-operations"><div class="panel-heading"><div><h2>Galactic operations</h2><span>SEALED FLEET ORDERS · ONE ACTION EACH · EXECUTE AT ROUND RESOLUTION</span></div><span class="tag">${orders.length} FLEET ORDER${orders.length===1?'':'S'}</span></div><div class="action-budget-note"><strong>${f.actions} general actions remaining</strong><p>Each fleet receives one movement or raid order per round. Your other actions can fund research, construction, surveys, recruitment, and invasions.</p>${btn('Choose an available action','spend-actions',{small:true})}</div><div class="operations-grid"><div><h3>Initiative bid</h3><p class="microcopy">Commit fuel for priority choice of an execution slot. Every empire pays its bid. You may revise your bid before resolving the round.</p><form id="initiative-form"><label>Fuel in escrow<input name="bid" type="number" min="0" max="${Math.min(12,f.fuel+f.initiativeBid)}" value="${f.initiativeBid}" required></label><label>Preferred slot<select name="slot">${[0,1,2].map(i=>`<option value="${i}" ${f.initiativeSlot===i?'selected':''}>${i+1}${i===0?' · first':''}</option>`).join('')}</select></label><button class="btn small" ${busy||state.result?'disabled':''}>Commit bid</button></form>${state.lastInitiative.length?`<p class="microcopy">Last execution order: ${state.lastInitiative.map(id=>faction(state,id).short).join(' → ')}</p>`:''}</div><div><h3>Imperial stability · zone ${stressZone(f)}/3</h3><div class="stress-meter" role="meter" aria-label="Imperial war stress" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${f.warStress}"><span style="width:${f.warStress/12*100}%"></span></div><p class="microcopy">War stress ${f.warStress}/12 · Commendations ${f.commendations}. Victories offset losses. Zone 1 adds one credit upkeep; zone 2 also reduces fuel regeneration; zone 3 also reduces commands by one.</p>${gameButton('Civilian relief · 3 credits + 1 material',{type:'civilian-relief'},{small:true})}<p class="microcopy">Relief reduces stress by three, once per round, and costs one action. Quiet periods also allow recovery.</p></div></div><div class="fleet-order-list">${orders.length?orders.map(o=>`<div><span><b>${o.type==='move'?'Fleet movement':'Convoy raid'}</b> · ${esc(sector(state,o.from).name)} → ${esc(sector(state,o.to).name)}<small>${o.shipCount||'Available'} vessels · ${o.fuelCost} fuel reserved · one action committed</small></span>${gameButton('Cancel',{type:'cancel-fleet-order',order:o.id},{small:true})}</div>`).join(''):'<p class="microcopy">No fleet orders committed. Select a fleet on the map to plot movement or a convoy raid. Rival orders remain hidden until execution.</p>'}</div></section>`;}
function galacticInfrastructure(x){const status=x.owner==='p'?convoyStatus(state,x):null,jobs=state.shipConstruction.filter(q=>q.sector===x.id&&q.owner==='p');return `<div class="infrastructure-summary"><span class="eyebrow">GALACTIC INFRASTRUCTURE</span>${x.owner==='p'?`<p>Shipyard capacity ${yardCapacity(x)} · ${jobs.length} vessel${jobs.length===1?'':'s'} pending</p><p>Convoy: ${esc(status.reason)} · ${Math.round(status.efficiency*100)}% physical deliveries</p><p class="microcopy">${status.route?status.route.map(id=>esc(sector(state,id).name)).join(' → '):'Half of physical output remains available locally. Science is unaffected.'}</p>${jobs.map(q=>`<p class="microcopy">Vessel ready at round ${q.readyRound} upkeep</p>`).join('')}${!x.relay?gameButton('Build transit relay · 4 materials + 2 credits',{type:'build-relay',sector:x.id},{small:true}):'<p class="microcopy">Transit relay active · direct travel to friendly relays</p>'}`:x.relay?'<p class="microcopy">Transit relay present. Allied access requires mutual transit.</p>':''}${fleetCommitted(state,'p',x.id)?'<p class="microcopy">Fleet committed. Cancel its order before loading troops or launching an invasion.</p>':''}</div>`;}

function saveSlot(i){try{const slots=read(KEY+'.slots',{});slots[i]={name:state.name,round:state.round,savedAt:Date.now(),game:state};localStorage.setItem(KEY+'.slots',JSON.stringify(slots));savesDialog();toast(`Saved to slot ${i}.`);}catch{toast('Unable to save on this device. Export a file instead.');}}
let pendingImport=null;
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>3_000_000)throw new Error('Save files must be smaller than 3 MB.');pendingImport=validateSave(JSON.parse(await file.text()));showDialog('Import campaign?',`<p>Load ${esc(pendingImport.name)}, round ${pendingImport.round}? Your current campaign will be backed up automatically.</p>${btn('Cancel','saves')}${btn('Import campaign','confirm-import',{primary:true})}`);}catch(err){toast(`Import rejected: ${err.message}`);}});
document.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);if(e.target.id==='initiative-form'){apply({type:'initiative',bid:Number(data.get('bid')),slot:Number(data.get('slot'))});return;}if(e.target.id==='new-form'){state=newGame({...Object.fromEntries(data),operations:true});state.worldCampaigns=true;view='galaxy';selected=state.sectors.find(x=>x.owner==='p').id;campaignId=null;groundSelected=null;moveFrom=null;persist();closeDialog();render();toast('Command established. Your campaign begins.');}if(e.target.id==='settings-form'){settings={motion:data.has('motion'),sound:data.has('sound')};try{localStorage.setItem(KEY+'.settings',JSON.stringify(settings));}catch{}closeDialog();render();toast('Preferences saved.');}if(e.target.id==='blueprint-form'){apply({type:'blueprint',blueprint:{weapon:Number(data.get('weapon')),shield:Number(data.get('shield')),transport:Number(data.get('transport'))}});}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&moveFrom){moveFrom=null;render();}});
window.addEventListener('pagehide',()=>{try{const saved=read(KEY+'.auto',null)?.game;if(!saved||saved.id!==state.id||(saved.revision||0)<=(state.revision||0))localStorage.setItem(KEY+'.auto',encodeSave(state));}catch{}});
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=0.3.1',{updateViaCache:'none'}).catch(()=>{});

function galacticMapOverlays(position){const paths=colonies(state).map(world=>{const route=convoyStatus(state,world).route;if(!route||route.length<2)return '';return '<polyline class="convoy-path" points="'+route.map(id=>{const p=position(sector(state,id));return p.x+','+p.y;}).join(' ')+'"/>';}).join('');const orders=state.fleetOrders.filter(o=>o.owner==='p').map(o=>'<polyline class="fleet-order-path" points="'+o.route.map(id=>{const p=position(sector(state,id));return p.x+','+p.y;}).join(' ')+'"/>').join('');const markers=state.sectors.filter(x=>x.revealed).map(x=>{const p=position(x),pending=state.shipConstruction.filter(q=>q.owner==='p'&&q.sector===x.id).length;return (x.relay?'<text class="network-mark" x="'+(p.x-28)+'" y="'+(p.y-14)+'">◇</text>':'')+(x.owner==='p'?'<text class="yard-mark" x="'+(p.x+18)+'" y="'+(p.y+5)+'">▥'+pending+'</text>':'');}).join('');return '<g pointer-events="none">'+paths+orders+markers+'</g>';}


function spendActionsDialog(){const choices=spendingChoices(state),available=choices.filter(c=>c.available),blocked=choices.filter(c=>!c.available),remaining=faction(state).actions;const row=c=>`<div class="spending-choice"><div><strong>${esc(c.label)}</strong><small>${esc(c.category)} · 1 action · ${esc(c.cost)}</small>${c.available?'':`<p class="microcopy">${esc(c.reason)}</p>`}</div>${btn('Spend 1 action','spend-choice',{small:true,primary:c.available,disabled:!c.available||busy,data:`data-command="${esc(JSON.stringify(c.action))}"`})}</div>`;showDialog('Spend your actions',`<p class="dialog-intro"><strong>${remaining} general actions remaining.</strong> A fleet can receive one movement or raid order per round. The remaining actions are available for the choices below.</p>${remaining===0?'<p>All actions spent. Close this panel and resolve the round when ready.</p>':available.length?'':'<p>No affordable actions are currently available. The reasons are listed below; you can resolve the round with unused actions.</p>'}${available.map(row).join('')}<details><summary>Unavailable choices · ${blocked.length}</summary>${blocked.map(row).join('')}</details>`);}

function worldCampaignView(c){const summary=campaignCycleSummary(c),ready=!!c.operational.winner||c.operational.round>=c.operationalTargetRound,href='./full/campaign.html?v=0.3.1&campaign='+encodeURIComponent(c.id)+'&galaxy='+encodeURIComponent(state.id)+(practice?'&practice=1':'');return `<div class="strategic-strip"><div><span class="eyebrow">WORLD-SCALE PLANETARY CAMPAIGN · ${c.operational.atlas.regions.length} HEX REGIONS</span><strong>${esc(c.name)}</strong><span>${ready?'Operational cycles complete. Resolve the galactic round to settle results or continue.':'Complete two operational cycles before resolving the galactic round.'}</span></div>${btn('Open province campaign','open-world',{primary:true,data:`data-href="${esc(href)}"`})}</div><div class="operation-stats"><div><span>Operational round</span><strong>${c.operational.round}</strong></div><div><span>Phase</span><strong>${esc(c.operational.phase)}</strong></div><div><span>Expeditionary units</span><strong>${summary.attacking}</strong></div><div><span>Defending units</span><strong>${summary.defending}</strong></div></div><section class="panel"><div class="panel-heading"><h2>Planetary provinces and sea regions</h2><span>${c.operational.polities.length} REGIONAL COMMANDS</span></div><div class="linked-world-preview" inert aria-hidden="true">${renderAtlas(c.operational.atlas,{commands:c.operational.commands})}</div></section><section class="panel inspector-body"><h2>Orbital support</h2><p>Local fuel, alloy, and materiel support the surface campaign. Only successful planetary conquest transfers ownership. Supplies require orbital access.</p><div class="action-pair">${gameButton('Deliver 2 energy + 2 alloy',{type:'supply',campaign:c.id},{small:true})}${gameButton('Deliver 5 materiel · 5 credits',{type:'supply',campaign:c.id,amount:{fuel:0,alloy:0,materiel:5}},{small:true})}${surfaceReinforcementButtons(c)}${c.attacker==='p'?gameButton('Evacuate expedition',{type:'withdraw',campaign:c.id},{small:true,danger:true}):''}</div></section>`;}
window.addEventListener('pageshow',event=>{if(!event.persisted)return;try{const latest=validateSave(read(KEY+'.auto',null));if(latest.id===state.id){state=latest;state.worldCampaigns=true;render();}}catch{}});
window.addEventListener('storage',event=>{if(event.key!==KEY+'.auto'||busy)return;try{const latest=validateSave(JSON.parse(event.newValue));if(latest.id===state.id){state=latest;state.worldCampaigns=true;render();}}catch{}});

function render(){renderView();applyResourceTerminology(document.querySelector("#app"));}

function showDialog(title,body){showDialogView(energyText(title),body);applyResourceTerminology(document.querySelector("#dialog"));}

function surfaceReinforcementButtons(c){const world=sector(state,c.sector),fleet=world.fleets.p;if(!fleet?.troops)return '';const regions=c.operational.atlas.regions.filter(r=>r.port&&controlledRegionalCommands(c,'p').includes(r.controller));return regions.map(r=>gameButton('Land '+Math.min(8,fleet.troops)+' cohorts · '+r.name+' · 1 energy',{type:'surface-reinforce',campaign:c.id,province:r.id,troops:Math.min(8,fleet.troops)},{small:true})).join('');}
